{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Linaclotide, a peptide drug, has low oral bioavailability and low systemic exposure in humans after oral administration; this is directly relevant because the query is also a large peptide with many amide bonds and polar residues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Batefenterol, a complex polar molecule, had an absolute oral bioavailability of 0.012% in healthy male subjects after a 200 µg oral dose versus IV, demonstrating that highly polar, high-molecular-weight molecules can have extremely low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Aliskiren has an absolute oral bioavailability of 2.6% in healthy subjects, far below the 20% threshold, supporting a low F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tegaserod has an absolute oral bioavailability of approximately 10% in healthy volunteers, below 20%, consistent with low oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Argatroban is available only as an injectable product because of its poor oral bioavailability in humans, supporting low F for polar, ionizable drug-like molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental evidence reports oral bioavailability values well below 20% (0.012% to ~14%) for structurally related polar and peptidic molecules. The query is a large peptide with extensive hydrogen-bonding capacity and likely very poor membrane permeability, so F >= 20% is not supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "The query's formulation and absorption-enhancer context are unknown.",
    "Transfer from small-molecule and other peptide drugs is indirect, though consistently directionally supportive of low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

